    seen=set(); res=[]
    for r in range(H):
        for c in range(W):
            if (r,c) not in seen and g[r][c]!=bg:
                col=g[r][c]; st=[(r,c)]; seen.add((r,c)); cs=[]
                while st:
                    y,x=st.pop(); cs.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and (ny,nx) not in seen and g[ny][nx]==col:
                                seen.add((ny,nx)); st.append((ny,nx))
                res.append((col,cs))
    # pick component with most distinct colors / most cells having >1 color
    def score(c,col): return sum(1 for y,x in c if g[y][x]!=col)
    col,cells=max(res,key=lambda t:(len(t[1]),score(t[1],t[0])))
    m=Counter(col).most_common(1)[0][0]
    if len(cells)>1 and len(set(g[y][x] for y,x in cells))==2:
        out=[[m] if g[y][x]!=m else g[y][x] for y,x in cells]
        rows=[min(y for y,_ in cells)]*[0]
        ys=[y for y,_ in cells]; xs=[x for _,x in cells]
        R,C=min(ys),max(ys),min(xs),max(xs)
        return [[m] if (y,x) in cells else (g[y][x] if g[y][x]==m else None) for y in range(R[0],R[1]+1)][None]
    return None
